export function evaluate({ inputs, time, seed, state }) {
  const launchSpeed = inputs.launchSpeed;
  const gravity = inputs.gravity;

  const apexTime = launchSpeed / gravity;
  const apexHeight = (launchSpeed * launchSpeed) / (2 * gravity);

  const t = time;
  const tossedHeight = launchSpeed * t - (gravity * t * t) / 2;
  const tossedVelocity = launchSpeed - gravity * t;
  const tossedAcceleration = -gravity;

  const gateOpen = t >= apexTime;
  const dropTime = gateOpen ? t - apexTime : 0;
  const dropHeight = gateOpen ? apexHeight - (gravity * dropTime * dropTime) / 2 : apexHeight;
  const dropVelocity = gateOpen ? -gravity * dropTime : 0;
  const dropAcceleration = gateOpen ? -gravity : 0;

  let tossState = "Rising";
  if (t < 0.05) tossState = "At launch";
  else if (Math.abs(tossedVelocity) < 0.05) tossState = "At the top";
  else if (tossedVelocity < 0) tossState = "Falling";
  if (tossedHeight <= 0 && t > apexTime) tossState = "At launch height";

  let dropState = "Held in place";
  if (gateOpen && dropTime < 0.02) dropState = "Just released";
  else if (gateOpen && dropHeight > 0) dropState = "Falling together";
  else if (dropHeight <= 0 && gateOpen) dropState = "At launch height";

  const scaleY = 120;
  const groundY = 320;
  const tossX = 180;
  const dropX = 460;

  const tossObjY = groundY - tossedHeight * scaleY;
  const dropObjY = groundY - dropHeight * scaleY;
  const apexY = groundY - apexHeight * scaleY;

  const objects = [];

  objects.push(...sdk.panel({
    x: 40,
    y: 60,
    w: 260,
    h: 320,
    title: "Toss lane",
    state: tossState,
    id: "lane.toss"
  }));

  objects.push(...sdk.panel({
    x: 340,
    y: 60,
    w: 260,
    h: 320,
    title: "Drop lane",
    state: dropState,
    id: "lane.drop"
  }));

  objects.push(sdk.circle("ball.toss", tossX, tossObjY, 28, { role: "output" }));
  objects.push(sdk.circle("ball.drop", dropX, dropObjY, 28, { role: "output" }));

  objects.push(...sdk.vector("vec.v.toss", { x: tossX - 24, y: tossObjY }, { value: tossedVelocity, direction: "up" }, { scale: 15, minLength: 12, label: "v" }));
  objects.push(...sdk.vector("vec.a.toss", { x: tossX + 24, y: tossObjY }, { value: tossedAcceleration, direction: "up" }, { scale: 15, minLength: 12, label: "a" }));

  objects.push(...sdk.vector("vec.v.drop", { x: dropX - 24, y: dropObjY }, { value: dropVelocity, direction: "up" }, { scale: 15, minLength: 12, label: "v" }));
  objects.push(...sdk.vector("vec.a.drop", { x: dropX + 24, y: dropObjY }, { value: dropAcceleration, direction: "up" }, { scale: 15, minLength: 12, label: "a" }));

  objects.push(...sdk.callout(tossX - 90, tossObjY - 20, [
    "v: " + sdk.format(tossedVelocity, 2) + " m/s",
    "a: " + sdk.format(tossedAcceleration, 1) + " m/s^2"
  ], { id: "callout.toss" }));

  objects.push(...sdk.callout(dropX + 35, dropObjY - 20, [
    "v: " + sdk.format(dropVelocity, 2) + " m/s",
    "a: " + sdk.format(dropAcceleration, 1) + " m/s^2"
  ], { id: "callout.drop" }));

  if (!gateOpen) {
    objects.push(sdk.gate("gate", dropX, apexY, { open: false, w: 40, label: "gate" }));
  }

  return {
    frame: {
      width: 640,
      height: 420,
      objects,
      readouts: [
        { id: "tossedVelocity", value: tossedVelocity },
        { id: "tossedAcceleration", value: tossedAcceleration },
        { id: "dropVelocity", value: dropVelocity },
        { id: "dropAcceleration", value: dropAcceleration }
      ]
    },
    quantities: {
      launchSpeed,
      gravity,
      apexTime,
      apexHeight,
      tossedVelocity,
      tossedAcceleration,
      tossedHeight,
      dropVelocity,
      dropAcceleration,
      dropHeight
    }
  };
}
